import {
  PlayerInnings,
  BattingInnings,
  BowlingInnings,
  ImpactBreakdown,
  PlayerImpact,
  PlayerData,
} from './types';
import {
  extractBattingFeatures,
  extractBowlingFeatures,
  extractContextFeatures,
  extractPressureFeatures,
} from './featureEngineering';
import { calculateContextWeight } from './contextDetector';
import { calculatePressureWeight } from './pressureCalculator';
import mlWeightsData from '@/data/model_weights.json';

// Load ML-learned weights (generated by train_model.py)
const mlWeights: Record<string, unknown> | null = mlWeightsData as unknown as Record<string, unknown>;

/**
 * Check if ML weights are available
 */
export function hasMLWeights(): boolean {
  return mlWeights !== null && !!(mlWeights as Record<string, unknown>)?.batting_weights;
}

/**
 * Get ML model metrics for display
 */
export function getMLMetrics(): Record<string, unknown> | null {
  if (!mlWeights) return null;
  return (mlWeights as Record<string, unknown>).model_metrics as Record<string, unknown> || null;
}

/**
 * Get ML training info for display
 */
export function getMLTrainingInfo(): Record<string, unknown> | null {
  if (!mlWeights) return null;
  return (mlWeights as Record<string, unknown>).training_info as Record<string, unknown> || null;
}

/**
 * Soft-ratio: adjusts rule-based coefficients using ML importance without
 * letting any single weight explode. Computes ratio between ML weight and
 * a baseline, then damps it: ratio > 1 is compressed, ratio < 1 is expanded.
 * This preserves the ML's ranking of what matters while keeping scores stable.
 */
function mlRatio(mlWeight: number, baseline: number): number {
  const raw = (mlWeight || baseline) / baseline;
  // Dampen: sqrt pulls extreme ratios toward 1.0
  // e.g. 4.37x → 2.09x, 0.5x → 0.71x
  return Math.sqrt(raw);
}

/**
 * Performance Score for Batting
 * Uses ML-learned weights when available, falls back to rule-based
 */
function battingPerformanceScore(innings: BattingInnings): number {
  const features = extractBattingFeatures(innings);

  if (hasMLWeights()) {
    const w = (mlWeights as Record<string, Record<string, number>>).batting_weights;
    // ML importance ratios (dampened via sqrt to avoid explosion)
    const runsW = mlRatio(w.runs, 0.15);
    const srW = mlRatio(w.strike_rate, 0.04);
    const foursW = mlRatio(w.fours, 0.03);
    const sixesW = mlRatio(w.sixes, 0.03);

    let score =
      features.runs * 0.5 * runsW +
      features.strikeRate * 0.2 * srW +
      features.fours * 2 * foursW +
      features.sixes * 3 * sixesW;

    // Bonus for death-over runs
    const deathW = mlRatio(w.runs_in_death, 0.03);
    score += (innings.runsInDeath || 0) * 0.3 * deathW;

    return Math.max(0, score);
  }

  // Rule-based fallback
  return (
    features.runs * 0.5 +
    features.strikeRate * 0.2 +
    features.fours * 2 +
    features.sixes * 3
  );
}

/**
 * Performance Score for Bowling
 * Uses ML-learned weights when available, falls back to rule-based
 */
function bowlingPerformanceScore(innings: BowlingInnings): number {
  const features = extractBowlingFeatures(innings);

  if (hasMLWeights()) {
    const w = (mlWeights as Record<string, Record<string, number>>).bowling_weights;
    const wkW = mlRatio(w.wickets, 0.2);
    const dotW = mlRatio(w.dot_balls, 0.03);
    const ecoW = mlRatio(w.economy, 0.03);

    const ecoBonus = Math.max(0, (8 - features.economy)) * 3 * ecoW;
    let score =
      features.wickets * 15 * wkW +
      features.dotBalls * 1 * dotW +
      ecoBonus;

    // Bonus for death-over wickets
    const deathWkW = mlRatio(w.wickets_in_death, 0.06);
    score += (innings.wicketsInDeath || 0) * 5 * deathWkW;

    return Math.max(0, score);
  }

  // Rule-based fallback
  const ecoBonus = Math.max(0, (8 - features.economy)) * 3;
  return (
    features.wickets * 15 +
    features.dotBalls * 1 +
    ecoBonus
  );
}

/**
 * Context weight using ML-learned multipliers when available
 */
function getContextWeight(innings: PlayerInnings): number {
  if (hasMLWeights()) {
    const cm = (mlWeights as Record<string, Record<string, number>>).context_multipliers;
    const context = extractContextFeatures(innings);

    // Use separate phase weights for batting vs bowling
    if (innings.type === 'bowling') {
      // Bowling: powerplay wickets are gold, death is hardest to bowl
      const bowlingPhaseWeights: Record<string, number> = {
        powerplay: 1.3,
        middle: 1.0,
        death: cm.death || 1.06,
      };
      return bowlingPhaseWeights[context.overPhase] || 1.0;
    }

    // Batting: death overs hardest, powerplay easiest
    let weight = cm[context.overPhase] || 1.0;
    if (context.isChasing) {
      weight *= (cm.chasing || 1.1);
    }
    return weight;
  }

  const context = extractContextFeatures(innings);
  return calculateContextWeight(context, innings.type as 'batting' | 'bowling');
}

/**
 * Pressure weight using ML-learned multipliers when available
 */
function getPressureWeight(innings: PlayerInnings): number {
  if (hasMLWeights()) {
    const pm = (mlWeights as Record<string, Record<string, number>>).pressure_multipliers;
    const pressure = extractPressureFeatures(innings);
    let weight = 1.0;

    if (pressure.requiredRunRate > 10) {
      weight = pm.rrr_high || 1.4;
    } else if (pressure.requiredRunRate > 8) {
      weight = pm.rrr_medium || 1.2;
    } else if (pressure.requiredRunRate > 6) {
      weight = 1.0 + (pm.rrr_medium - 1.0) * 0.5 || 1.1;
    }

    if (pressure.wicketsRemaining < 4) {
      weight += pm.wickets_low || 0.2;
    } else if (pressure.wicketsRemaining < 6) {
      weight += (pm.wickets_low || 0.2) * 0.5;
    }

    if (pressure.matchStage === 'late') {
      weight += 0.1;
    }

    return Math.min(weight, 2.0);
  }

  const pressure = extractPressureFeatures(innings);
  return calculatePressureWeight(pressure);
}

/**
 * Knockout match multiplier — playoff/final performances weighted higher
 */
function getKnockoutMultiplier(innings: PlayerInnings): number {
  if ('isKnockout' in innings && innings.isKnockout) {
    return 1.15; // 15% boost for knockout matches
  }
  return 1.0;
}

/**
 * Defending pressure bonus for bowlers
 * When bowling in 2nd innings defending a low total, good economy is more impactful
 */
function getDefendingPressureBonus(innings: PlayerInnings): number {
  if (innings.type !== 'bowling') return 0;
  // Bowler is defending when they bowl in the 2nd innings (opponent is chasing)
  // isChasing on bowling innings means the bowler's team is chasing — so !isChasing means defending
  if (innings.isChasing) return 0; // bowler's team is chasing, not defending

  const firstTotal = ('firstInningsTotal' in innings ? innings.firstInningsTotal : 0) || 0;
  if (firstTotal <= 0) return 0;

  const bowling = innings as BowlingInnings;
  const eco = bowling.economy;

  // Low total defense (< 150): bowler keeping economy < 6 gets a bonus
  if (firstTotal < 150 && eco < 6) {
    return (6 - eco) * 2; // up to ~12 bonus points
  }
  // Medium total defense (150-170): economy < 7 gets a smaller bonus
  if (firstTotal < 170 && eco < 7) {
    return (7 - eco) * 1.5; // up to ~10.5 bonus points
  }
  return 0;
}

/**
 * Calculate raw impact for a single innings
 * Impact = Performance x Context x Pressure x Knockout
 * + Defending pressure bonus for bowlers
 */
export function calculateInningsImpact(innings: PlayerInnings): ImpactBreakdown {
  let performanceScore: number;

  if (innings.type === 'batting') {
    performanceScore = battingPerformanceScore(innings);
  } else {
    performanceScore = bowlingPerformanceScore(innings);
    // Add defending pressure bonus for bowlers
    performanceScore += getDefendingPressureBonus(innings);
  }

  const contextWeight = getContextWeight(innings);
  const pressureWeight = getPressureWeight(innings);
  const knockoutMultiplier = getKnockoutMultiplier(innings);

  const rawImpact = performanceScore * contextWeight * pressureWeight * knockoutMultiplier;

  // Normalize to 0-100 using sigmoid-like curve for better spread
  // This avoids hard ceiling and spreads scores across the full 0-100 range
  // Median raw impact (~40 bat, ~25 bowl) maps to ~50, exceptional maps to 80-95
  const median = innings.type === 'batting' ? 40 : 28;
  const steepness = innings.type === 'batting' ? 0.026 : 0.030;
  // Logistic normalization: pushes scores into 0-100 with natural spread
  const normalizedImpact = Math.min(100, Math.max(0,
    100 / (1 + Math.exp(-steepness * (rawImpact - median)))
  ));

  return {
    performanceScore,
    contextWeight,
    pressureWeight,
    rawImpact,
    normalizedImpact,
  };
}

/**
 * Exponential recency decay for rolling innings.
 * Latest innings has ~5x the weight of the oldest (10th) innings.
 * decay = 0.82^(distance from latest)
 * Position 1 (latest) = 1.0, Position 10 (oldest) = 0.82^9 ≈ 0.17
 */
function getRecencyWeight(index: number, total: number): number {
  const distFromLatest = total - 1 - index; // 0 = latest, total-1 = oldest
  return Math.pow(0.82, distFromLatest);
}

/**
 * Calculate rolling impact score for a player's last N innings
 */
export function calculateRollingImpact(innings: PlayerInnings[], n: number = 10): number {
  if (innings.length === 0) return 50; // baseline

  // Sort by date, most recent last
  const sorted = [...innings].sort((a, b) => (a.date || '').localeCompare(b.date || ''));
  const recent = sorted.slice(-n);

  let weightedSum = 0;
  let totalWeight = 0;

  recent.forEach((inn, index) => {
    const impact = calculateInningsImpact(inn);
    const weight = getRecencyWeight(index, recent.length);
    weightedSum += impact.normalizedImpact * weight;
    totalWeight += weight;
  });

  return totalWeight > 0 ? weightedSum / totalWeight : 50;
}

/**
 * Get recent form (last 10 innings impact scores)
 */
export function getRecentForm(innings: PlayerInnings[], n: number = 10): number[] {
  const sorted = [...innings].sort((a, b) => (a.date || '').localeCompare(b.date || ''));
  const recent = sorted.slice(-n);
  return recent.map(inn => calculateInningsImpact(inn).normalizedImpact);
}

/**
 * Determine player role based on innings data
 */
function determineRole(innings: PlayerInnings[]): 'batsman' | 'bowler' | 'allrounder' {
  const batting = innings.filter(i => i.type === 'batting');
  const bowling = innings.filter(i => i.type === 'bowling');

  const batCount = batting.length;
  const totalBallsBowled = bowling.reduce((s, i) => s + (i as BowlingInnings).ballsBowled, 0);

  if (totalBallsBowled > batCount * 12) {
    if (batting.some(b => (b as BattingInnings).runs > 30)) return 'allrounder';
    return 'bowler';
  }
  if (totalBallsBowled > batCount * 6) return 'allrounder';
  return 'batsman';
}

/**
 * Calculate complete player impact profile
 */
export function calculatePlayerImpact(name: string, data: PlayerData): PlayerImpact {
  const { team, innings } = data;

  const battingInnings = innings.filter(i => i.type === 'batting') as BattingInnings[];
  const bowlingInnings = innings.filter(i => i.type === 'bowling') as BowlingInnings[];

  const totalRuns = battingInnings.reduce((s, i) => s + i.runs, 0);
  const totalOuts = battingInnings.filter(i => i.isOut).length;
  const battingAvg = totalOuts > 0 ? totalRuns / totalOuts : totalRuns;

  const totalWickets = bowlingInnings.reduce((s, i) => s + i.wickets, 0);
  const totalRunsConceded = bowlingInnings.reduce((s, i) => s + i.runsConceded, 0);
  const bowlingAvg = totalWickets > 0 ? totalRunsConceded / totalWickets : 999;

  const totalBallsFaced = battingInnings.reduce((s, i) => s + i.ballsFaced, 0);
  const overallSR = totalBallsFaced > 0 ? (totalRuns / totalBallsFaced) * 100 : 0;

  const totalBallsBowled = bowlingInnings.reduce((s, i) => s + i.ballsBowled, 0);
  const overallEco = totalBallsBowled > 0 ? (totalRunsConceded / (totalBallsBowled / 6)) : 0;

  const matchIds = new Set(innings.map(i => i.matchId));
  const matchesPlayed = matchIds.size;

  const wins = innings.filter(i => i.matchResult === 'won');
  const uniqueWinMatches = new Set(wins.map(i => i.matchId)).size;
  const winRate = matchesPlayed > 0 ? (uniqueWinMatches / matchesPlayed) * 100 : 0;

  const impactScore = calculateRollingImpact(innings, 10);
  const recentForm = getRecentForm(innings, 10);
  const role = determineRole(innings);

  const seasons = innings.map(i => i.season).filter(Boolean);
  const lastSeason = seasons.length > 0 ? seasons.sort().pop()! : '';

  return {
    name,
    team,
    impactScore: Math.round(impactScore * 10) / 10,
    matchesPlayed,
    battingAvg: Math.round(battingAvg * 100) / 100,
    bowlingAvg: Math.round(bowlingAvg * 100) / 100,
    strikeRate: Math.round(overallSR * 100) / 100,
    economy: Math.round(overallEco * 100) / 100,
    recentForm: recentForm.map(f => Math.round(f * 10) / 10),
    role,
    winRate: Math.round(winRate * 10) / 10,
    lastSeason,
  };
}

/**
 * Calculate match-level impact for all players in a match
 */
export function calculateMatchImpact(
  matchId: string,
  allPlayerData: Record<string, PlayerData>
): { name: string; team: string; impact: number; breakdown: ImpactBreakdown }[] {
  const results: { name: string; team: string; impact: number; breakdown: ImpactBreakdown }[] = [];

  for (const [name, data] of Object.entries(allPlayerData)) {
    const matchInnings = data.innings.filter(i => i.matchId === matchId);
    if (matchInnings.length === 0) continue;

    let totalImpact = 0;
    let bestBreakdown: ImpactBreakdown | null = null;

    for (const inn of matchInnings) {
      const breakdown = calculateInningsImpact(inn);
      totalImpact += breakdown.normalizedImpact;
      if (!bestBreakdown || breakdown.normalizedImpact > bestBreakdown.normalizedImpact) {
        bestBreakdown = breakdown;
      }
    }

    const avgImpact = totalImpact / matchInnings.length;

    results.push({
      name,
      team: data.team,
      impact: Math.round(avgImpact * 10) / 10,
      breakdown: bestBreakdown!,
    });
  }

  return results.sort((a, b) => b.impact - a.impact);
}
